//! Synthetic fixture generator (CLAUDE.md: "Use synthetic fixtures only,
//! generated by xtask/"). Produces a diverse, fully synthetic test corpus
//! nested under a handful of "project" folders (mimicking a real migration
//! source tree), with:
//!
//! - Multi-way exact duplicates: each original gets 2 byte-identical copies
//!   in separate GUID-named subfolders (a 3-member duplicate group).
//! - Genuine multi-generation near-duplicates for txt/html/htm: each
//!   original produces a 2-generation version chain (gen1 adds a line to
//!   the original, gen2 adds another line to gen1), nested progressively
//!   deeper to mimic real version drift.
//! - Decoy files with genuinely unrelated content (not just a different
//!   embedded number) for every format `similar` supports, so there are
//!   real true-negatives to sift through, not just near-identical samples.
//!
//! The output is deterministic (fixed RNG seed) so committing it doesn't
//! churn on every regeneration unless the generator itself changes.
//!
//! Usage: `cargo run -p xtask -- [out_dir] [samples_per_format]`
//! Defaults: out_dir = "data", samples_per_format = 4.

use std::fs;
use std::io::{Cursor, Write};
use std::path::{Path, PathBuf};

const FIXED_SEED: u64 = 0xD21A_5EED_C0FF_EE42;
const PROJECTS: &[&str] = &["project-alpha", "project-beta", "project-gamma"];
const DECOYS_PER_FORMAT: usize = 2;

// Combinatorial decoy sentences: each decoy gets a distinct subject/verb/
// object combination (keyed by a seed unique across all format+index
// combinations), so decoys are genuinely unrelated to each other, not just
// to the real samples. A single shared sentence would make every decoy
// cross-match every other decoy as a near-duplicate.
const DECOY_SUBJECTS: &[&str] = &[
    "the committee",
    "migratory birds",
    "volcanic activity",
    "the research team",
    "quarterly revenue",
    "the shipping container",
    "wildlife biologists",
    "the software update",
];
const DECOY_VERBS: &[&str] = &[
    "reviewed",
    "traveled across",
    "reshaped",
    "documented",
    "exceeded",
    "arrived at",
    "tracked",
    "improved",
];
const DECOY_OBJECTS: &[&str] = &[
    "the annual budget proposal",
    "the northern coastline",
    "several remote field stations",
    "expectations for the fiscal year",
    "the regional distribution center",
    "population trends in the reserve",
    "startup latency across all regions",
];

fn decoy_sentence(seed: usize) -> String {
    let subject = DECOY_SUBJECTS[seed % DECOY_SUBJECTS.len()];
    let verb = DECOY_VERBS[(seed / DECOY_SUBJECTS.len()) % DECOY_VERBS.len()];
    let object =
        DECOY_OBJECTS[(seed / (DECOY_SUBJECTS.len() * DECOY_VERBS.len())) % DECOY_OBJECTS.len()];
    format!("{subject} {verb} {object}")
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let out_dir = args
        .first()
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("data"));
    let samples_per_format: usize = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(4);

    match generate_fixtures(&out_dir, samples_per_format) {
        Ok(count) => {
            println!(
                "xtask: generated {count} format(s) x {samples_per_format} sample(s) under {}",
                out_dir.display()
            );
            println!(
                "xtask: note - png/jpg/jpeg/gif/bmp/tiff/msg fixtures carry correct magic-number headers but \
                 are not fully valid/renderable files. The tool only exact-hashes them today (no image \
                 decoding or MSG parsing), so this is sufficient for current test coverage."
            );
        }
        Err(err) => {
            eprintln!("xtask: failed to generate fixtures: {err}");
            std::process::exit(1);
        }
    }
}

struct Format {
    ext: &'static str,
    make: fn(usize) -> Vec<u8>,
    /// `Some` for every format `similar` supports, producing content with
    /// genuinely different wording (not just a different number) so there
    /// are real true-negatives in the corpus.
    decoy: Option<fn(usize) -> Vec<u8>>,
    /// txt/html/htm duplicates become a 2-generation near-duplicate chain;
    /// every other format's duplicates are byte-identical (exact
    /// duplicates).
    mutatable_text: bool,
}

